async function ocrPages(images){
 if(images.length>5)throw Error('Scanned-document OCR is limited to 5 pages per check.');
 const Tesseract=await loadTesseract(),pages=[],confidences=[];
 const worker=await Tesseract.createWorker('isl+eng',Tesseract.OEM.LSTM_ONLY,{workerPath:'/vendor/tesseract/worker.min.js',corePath:'/vendor/tesseract/tesseract-core-lstm.wasm.js',langPath:'/vendor/tesseract/lang',gzip:true,logger:message=>{if(message.status==='recognizing text')result.innerHTML='<p>Reading scanned pages locally… '+Math.round((message.progress||0)*100)+'%</p>'}});
 try{
  for(let index=0;index<images.length;index++){
   result.innerHTML='<p>Reading scanned page '+(index+1)+' of '+images.length+' locally…</p>';
   const recognition=await worker.recognize(images[index]),text=recognition.data?.text?.trim(),confidence=Number(recognition.data?.confidence);
   if(text){pages.push('[Scanned page '+(index+1)+']\n'+text);if(Number.isFinite(confidence))confidences.push(confidence)}
  }
 }finally{await worker.terminate()}
 if(!pages.length)throw Error('No readable text was found in the scanned pages. Try a clearer PDF or use manual entry.')
 return {text:pages.join('\n\n'),confidence:confidences.length?confidences.reduce((a,b)=>a+b,0)/confidences.length:null};
}
